+      <span className="min-w-0 flex-1">
+        <b className="block text-sm">Preguntas destacadas</b>
+        <small className="block text-[13px] opacity-70">{lineOf(session)}</small>
+      </span>
+      <Switch on={session.featuredQuestions} />
+    </button>
+  );
+};
